export function eligible(age) {
  if (!Number.isInteger(age) || age < 0) throw new Error("invalid age");
  return age >= 18;
}
import test from "node:test";
import assert from "node:assert/strict";
import { eligible } from "./eligibility.mjs";
test("eligibility boundary", () => {
  assert.equal(eligible(17), false);
  assert.equal(eligible(18), true);
  assert.equal(eligible(19), true);
});

test("rejects invalid ages", () => {
  for (const age of [-1, 1.5, NaN]) {
    assert.throws(() => eligible(age), { message: "invalid age" });
  }
});
